 "content": "def transform(grid):
    """Overlay the non-background marks from the two panels around the divider."""
    h, w = len(grid), len(grid[0])
    mid = w // 2
    left = [row[:mid] for row in grid]
    right = [row[mid + 1:] for row in grid]
    if any(len(row) != mid for row in left + right):
        raise ValueError("expected two equal panels around a central divider")

    left_colors = {v for row in left for v in row}
    right_colors = {v for row in right for v in row}
    shared = left_colors & right_colors
    if not shared:
        raise ValueError("panels have no shared background color")
    # The shared color is the background; if there are several shared colors,
    # choose the most frequent one across both panels.
    counts = {c: sum(v == c for row in left + right for v in row) for c in shared}
    background = max(shared, key=lambda c: counts[c])

    return [[2 if left[r][c] != background or right[r][c] != background else 3
             for c in range(mid)] for r in range(h)]
